const RESOLVE_EXTENSIONS = ['.ts', '.tsx', '.d.ts', '.mts', '.cts', '.js', '.jsx', '.mjs', '.cjs']
const INDEX_EXTENSIONS = ['.ts', '.tsx', '.d.ts', '.mts', '.cts', '.js', '.jsx', '.mjs', '.cjs']

/**
 * Parsed representation of a component path string.
 */
type ParsedComponentPath = {
  /** Whether the export name was explicitly provided (via `#` or `exportName`). */
  explicitExport: boolean
  /** The export name being referenced. Defaults to `'default'`. */
  exportName: string
  /** The file/module path portion (everything before an optional `#`). */
  path: string
}

/**
 * Static analysis result for a resolved module's exports.
 */
type ModuleExports = {
  hasDefault: boolean
  named: string[]
}

const pluginInit = ({ typescript: ts }: { typescript: TS }): { create(info: tsModule.server.PluginCreateInfo): tsModule.LanguageService } => {
  return {
    create(info) {
      const proxy = createProxy(ts, info)
      return proxy
    },
  }
}

export default pluginInit

function createProxy(ts: TS, info: tsModule.server.PluginCreateInfo): tsModule.LanguageService {
  const base = info.languageService
  const host = info.languageServiceHost

  // Build a proxy that delegates everything to the base language service,
  // overriding only the methods we augment.
  const proxy = Object.create(null) as tsModule.LanguageService
  for (const key of Object.keys(base) as Array<keyof tsModule.LanguageService>) {
    const value = base[key]
    // @ts-expect-error - generic passthrough
    proxy[key] = typeof value === 'function' ? (value as Function).bind(base) : value
  }

  const log = (msg: string) => {
    try {
      info.project?.projectService?.logger?.info?.(`[payload-ts-plugin] ${msg}`)
    } catch {
      // ignore logging failures
    }
  }

  const getBaseDir = (): string => {
    const configured = (info.config as { baseDir?: string } | undefined)?.baseDir
    if (configured) {
      return nodePath.isAbsolute(configured)
        ? configured
        : nodePath.join(host.getCurrentDirectory(), configured)
    }
    return host.getCurrentDirectory()
  }

  proxy.getSemanticDiagnostics = (fileName) => {
    const prior = base.getSemanticDiagnostics(fileName)
    try {
      const extra = computeDiagnostics(ts, info, host, getBaseDir(), fileName)
      if (extra.length) {
        return [...prior, ...extra]
      }
      return prior
    } catch (e) {
      log(`getSemanticDiagnostics failed: ${String(e)}`)
      return prior
    }
  }

  proxy.getCompletionsAtPosition = (fileName, position, options, formattingSettings) => {
    try {
      const ours = computeCompletions(ts, info, host, getBaseDir(), fileName, position)
      if (ours) {
        return ours
      }
    } catch (e) {
      log(`getCompletionsAtPosition failed: ${String(e)}`)
    }
    return base.getCompletionsAtPosition(fileName, position, options, formattingSettings)
  }

  proxy.getDefinitionAndBoundSpan = (fileName, position) => {
    try {
      const ours = computeDefinition(ts, info, host, getBaseDir(), fileName, position)
      if (ours) {
        return ours
      }
    } catch (e) {
      log(`getDefinitionAndBoundSpan failed: ${String(e)}`)
    }
    return base.getDefinitionAndBoundSpan(fileName, position)
  }

  return proxy
}

// ---------------------------------------------------------------------------
// Diagnostics
// ---------------------------------------------------------------------------

function computeDiagnostics(
  ts: TS,
  info: tsModule.server.PluginCreateInfo,
  host: tsModule.LanguageServiceHost,
  baseDir: string,
  fileName: string,
): tsModule.Diagnostic[] {
  const program = info.languageService.getProgram()
  if (!program) {
    return []
  }
  const sourceFile = program.getSourceFile(fileName)
  if (!sourceFile) {
    return []
  }
  const checker = program.getTypeChecker()
  const diagnostics: tsModule.Diagnostic[] = []

  const references = collectReferences(ts, checker, sourceFile)

  for (const ref of references) {
    if (ref.form === 'string') {
      validateReference(ts, program, host, baseDir, sourceFile, {
        pathValueNode: ref.node,
        exportValueNode: ref.node,
        parsed: parseComponentPathString(ref.node.text),
        diagnostics,
        // For string form there is no separate export node; a missing export
        // diagnostic points at the whole string literal.
      })
    } else {
      // Object form.
      if (!ref.pathNode) {
        continue
      }
      const parsed = parseObjectForm(ref.pathNode.text, ref.exportNode?.text)
      validateReference(ts, program, host, baseDir, sourceFile, {
        pathValueNode: ref.pathNode,
        exportValueNode: ref.exportNode ?? ref.pathNode,
        parsed,
        diagnostics,
      })
    }
  }

  return diagnostics
}

function validateReference(
  ts: TS,
  program: tsModule.Program,
  host: tsModule.LanguageServiceHost,
  baseDir: string,
  sourceFile: tsModule.SourceFile,
  args: {
    diagnostics: tsModule.Diagnostic[]
    exportValueNode: tsModule.StringLiteralLike
    parsed: ParsedComponentPath
    pathValueNode: tsModule.StringLiteralLike
  },
): void {
  const { diagnostics, exportValueNode, parsed, pathValueNode } = args

  const resolved = resolveComponentPath(
    ts,
    host,
    program.getCompilerOptions(),
    baseDir,
    sourceFile.fileName,
    parsed.path,
  )

  if (!resolved) {
    diagnostics.push(
      makeDiagnostic(
        ts,
        sourceFile,
        pathValueNode,
        CODE_UNRESOLVED_PATH,
        `Cannot resolve Payload component path '${parsed.path}'. The file '${parsed.path}' could not be found on disk.`,
      ),
    )
    return
  }

  const moduleExports = getModuleExports(ts, program, host, resolved)

  if (parsed.exportName === 'default' && !parsed.explicitExport) {
    if (!moduleExports.hasDefault) {
      diagnostics.push(
        makeDiagnostic(
          ts,
          sourceFile,
          pathValueNode,
          CODE_UNRESOLVED_EXPORT,
          missingDefaultMessage(parsed.path),
        ),
      )
    }
    return
  }

  // Explicit export name (from `#` or `exportName`).
  if (parsed.exportName === 'default') {
    if (!moduleExports.hasDefault) {
      diagnostics.push(
        makeDiagnostic(
          ts,
          sourceFile,
          exportValueNode,
          CODE_UNRESOLVED_EXPORT,
          missingDefaultMessage(parsed.path),
        ),
      )
    }
    return
  }

  if (!moduleExports.named.includes(parsed.exportName)) {
    diagnostics.push(
      makeDiagnostic(
        ts,
        sourceFile,
        exportValueNode,
        CODE_UNRESOLVED_EXPORT,
        missingExportMessage(ts, parsed.path, parsed.exportName, moduleExports.named),
      ),
    )
  }
}

